def link(text,url,cl='text-link'):
 return f'<a class="{cl}" href="{escape(url,quote=True)}">{escape(text)} {icon("arrow")}</a>'

def button(text,url,cl='btn-gold'):
 return f'<a class="btn {cl}" href="{escape(url,quote=True)}">{escape(text)} {icon("arrow")}</a>'

